    struct Peripheral {
        name: String,
        description: String,
        base_address: u64,
        group_name: Option<String>,
        interrupts: Vec<Interrupt>,
        registers: Vec<RegisterCluster>,
    }

    #[derive(Debug, Clone)]
    struct Interrupt {
        name: String,
        description: String,
        value: u32,
    }

    #[derive(Debug, Clone)]
    enum RegisterCluster {
        Register(Register),
        Cluster(Cluster),
    }

    #[derive(Debug, Clone)]
    struct Register {
        name: String,
        description: String,
        address_offset: u64,
        size: u32,
        access: String,
        reset_value: u64,
        fields: Vec<Field>,
        dim: Option<u32>,
        dim_increment: Option<u64>,
        dim_index: Option<String>,
    }

    #[derive(Debug, Clone)]
    struct Field {
        name: String,
        description: String,
        bit_offset: u32,
        bit_width: u32,
    }

    #[derive(Debug, Clone)]
    struct Cluster {
        name: String,
        description: String,
        address_offset: u64,
        dim: Option<u32>,
        registers: Vec<Register>,
    }

    // Minimal XML parsing: we will use regex to extract

    fn extract_tag_content(xml: &str, tag: &str) -> Vec<String> {
        let mut res = Vec::new();
        let pattern = format!(r"<{}[^>]*>(.*?)</{}>", tag, tag);
        let re = regex::Regex::new(&pattern).unwrap();
        for cap in re.captures_iter(xml) {
            res.push(cap[1].to_string());
        }
        res
    }

    fn extract_single(xml: &str, tag: &str) -> Option<String> {
        let pattern = format!(r"<{}[^>]*>(.*?)</{}>", tag, tag);
        let re = regex::Regex::new(&pattern).unwrap();
        re.captures(xml).map(|c| c[1].trim().to_string())
    }

    // Parse device

    let device_name = extract_single(&svd_content, "name").unwrap_or_else(|| "DEVICE".to_string());
    let device_desc = extract_single(&svd_content, "description").unwrap_or_default();

    // cpu nvicPrioBits
    let cpu_block = extract_single(&svd_content, "cpu").unwrap_or_default();
    let nvic_bits = if cpu_block.contains("nvicPrioBits") {
        let pattern = r"<nvicPrioBits[^>]*>(\d+)</nvicPrioBits>";
        let re = regex::Regex::new(pattern).unwrap();
        re.captures(&cpu_block).and_then(|c| c[1].parse::<u8>().ok())
    } else {
        // try directly in whole file for <nvicPrioBits>
        let pattern = r"<nvicPrioBits[^>]*>(\d+)</nvicPrioBits>";
        let re = regex::Regex::new(pattern).unwrap();
        re.captures(&svd_content).and_then(|c| c[1].parse::<u8>().ok())
    };

    // peripherals
    let peripherals_block = {
        // find <peripherals> ... </peripherals>
        let re = regex::Regex::new(r"<peripherals[^>]*>(?s)(.*?)</peripherals>").unwrap();
        re.captures(&svd_content).map(|c| c[1].to_string()).unwrap_or_default()
    };

    // split peripherals by <peripheral> tags
    let mut peripherals: Vec<Peripheral> = Vec::new();
    let re_periph = regex::Regex::new(r"<peripheral[^>]*>(?s)(.*?)</peripheral>").unwrap();
    for cap in re_periph.captures_iter(&peripherals_block) {
        let periph_xml = &cap[1];
        let pname = extract_single(periph_xml, "name").unwrap_or_else(|| "PERIPH".to_string());
        let pdesc = extract_single(periph_xml, "description").unwrap_or_else(|| format!("{} peripheral", pname));
        let base_str = extract_single(periph_xml, "baseAddress").unwrap_or_else(|| "0".to_string());
        let base_addr = if base_str.starts_with("0x") || base_str.starts_with("0X") {
            u64::from_str_radix(base_str.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
        } else {
            base_str.parse::<u64>().unwrap_or(0)
        };
        let base_addr = base_addr + config.base_address_shift;

        let group_name = extract_single(periph_xml, "groupName");

        // interrupts
        let mut interrupts = Vec::new();
        let re_int = regex::Regex::new(r"<interrupt[^>]*>(?s)(.*?)</interrupt>").unwrap();
        for icap in re_int.captures_iter(periph_xml) {
            let int_xml = &icap[1];
            let iname = extract_single(int_xml, "name").unwrap_or_else(|| "IRQ".to_string());
            let idesc = extract_single(int_xml, "description").unwrap_or_default();
            let ival_str = extract_single(int_xml, "value").unwrap_or_else(|| "0".to_string());
            let ival = ival_str.parse::<u32>().unwrap_or(0);
            interrupts.push(Interrupt { name: iname, description: idesc, value: ival });
        }

        // registers
        let registers_block = {
            let re = regex::Regex::new(r"<registers[^>]*>(?s)(.*?)</registers>").unwrap();
            re.captures(periph_xml).map(|c| c[1].to_string()).unwrap_or_default()
        };

        let mut regs: Vec<RegisterCluster> = Vec::new();

        // For simplicity, only parse <register> tags directly, ignoring clusters for now, but we can parse clusters as well

        let re_reg = regex::Regex::new(r"<register[^>]*>(?s)(.*?)</register>").unwrap();
        for rcap in re_reg.captures_iter(&registers_block) {
            let reg_xml = &rcap[1];
            // Check if dim
            let dim = extract_single(reg_xml, "dim").and_then(|s| s.parse::<u32>().ok());
            let dim_inc_str = extract_single(reg_xml, "dimIncrement");
            let dim_inc = dim_inc_str.map(|s| {
                let s = s.trim();
                if s.starts_with("0x") || s.starts_with("0X") {
                    u64::from_str_radix(s.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
                } else {
                    s.parse::<u64>().unwrap_or(0)
                }
            });
            let dim_index = extract_single(reg_xml, "dimIndex");

            let rname = extract_single(reg_xml, "name").unwrap_or_else(|| "REG".to_string());
            let rdesc = extract_single(reg_xml, "description").unwrap_or_else(|| "".to_string());
            let offset_str = extract_single(reg_xml, "addressOffset").unwrap_or_else(|| "0".to_string());
            let offset = if offset_str.starts_with("0x") || offset_str.starts_with("0X") {
                u64::from_str_radix(offset_str.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
            } else {
                offset_str.parse::<u64>().unwrap_or(0)
            };
            let size_str = extract_single(reg_xml, "size").unwrap_or_else(|| "32".to_string());
            let size = size_str.parse::<u32>().unwrap_or(32);
            let access = extract_single(reg_xml, "access").unwrap_or_else(|| "read-write".to_string());
            let reset_str = extract_single(reg_xml, "resetValue").unwrap_or_else(|| "0".to_string());
            let reset = if reset_str.starts_with("0x") || reset_str.starts_with("0X") {
                u64::from_str_radix(reset_str.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
            } else {
                reset_str.parse::<u64>().unwrap_or(0)
            };

            // fields
            let mut fields = Vec::new();
            let fields_block = {
                let re = regex::Regex::new(r"<fields[^>]*>(?s)(.*?)</fields>").unwrap();
                re.captures(reg_xml).map(|c| c[1].to_string()).unwrap_or_default()
            };
            let re_field = regex::Regex::new(r"<field[^>]*>(?s)(.*?)</field>").unwrap();
            for fcap in re_field.captures_iter(&fields_block) {
                let field_xml = &fcap[1];
                let fname = extract_single(field_xml, "name").unwrap_or_else(|| "FIELD".to_string());
                let fdesc = extract_single(field_xml, "description").unwrap_or_default();
                let offset_str = extract_single(field_xml, "bitOffset").unwrap_or_else(|| "0".to_string());
                let bit_offset = offset_str.parse::<u32>().unwrap_or(0);
                let width_str = extract_single(field_xml, "bitWidth").unwrap_or_else(|| "1".to_string());
                let bit_width = width_str.parse::<u32>().unwrap_or(1);
                fields.push(Field { name: fname, description: fdesc, bit_offset, bit_width });
            }

            regs.push(RegisterCluster::Register(Register {
                name: rname,
                description: rdesc,
                address_offset: offset,
                size,
                access,
                reset_value: reset,
                fields,
                dim,
                dim_increment: dim_inc,
                dim_index,
            }));
        }

        // clusters: parse <cluster> simple
        let re_cluster = regex::Regex::new(r"<cluster[^>]*>(?s)(.*?)</cluster>").unwrap();
        for ccap in re_cluster.captures_iter(&registers_block) {
            let cl_xml = &ccap[1];
            let cname = extract_single(cl_xml, "name").unwrap_or_else(|| "CLUSTER".to_string());
            let cdesc = extract_single(cl_xml, "description").unwrap_or_default();
            let offset_str = extract_single(cl_xml, "addressOffset").unwrap_or_else(|| "0".to_string());
            let offset = if offset_str.starts_with("0x") || offset_str.starts_with("0X") {
                u64::from_str_radix(offset_str.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
            } else {
                offset_str.parse::<u64>().unwrap_or(0)
            };
            let dim = extract_single(cl_xml, "dim").and_then(|s| s.parse::<u32>().ok());
            // for simplicity, parse inner registers of cluster
            let mut inner_regs = Vec::new();
            let re_reg_inner = regex::Regex::new(r"<register[^>]*>(?s)(.*?)</register>").unwrap();
            for rcap in re_reg_inner.captures_iter(cl_xml) {
                let reg_xml = &rcap[1];
                let rname = extract_single(reg_xml, "name").unwrap_or_else(|| "REG".to_string());
                let rdesc = extract_single(reg_xml, "description").unwrap_or_default();
                let offset_str = extract_single(reg_xml, "addressOffset").unwrap_or_else(|| "0".to_string());
                let offset = if offset_str.starts_with("0x") || offset_str.starts_with("0X") {
                    u64::from_str_radix(offset_str.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
                } else {
                    offset_str.parse::<u64>().unwrap_or(0)
                };
                let size = extract_single(reg_xml, "size").and_then(|s| s.parse::<u32>().ok()).unwrap_or(32);
                inner_regs.push(Register {
                    name: rname,
                    description: rdesc,
                    address_offset: offset,
                    size,
                    access: "read-write".to_string(),
                    reset_value: 0,
                    fields: Vec::new(),
                    dim: None,
                    dim_increment: None,
                    dim_index: None,
                });
            }
            regs.push(RegisterCluster::Cluster(Cluster {
                name: cname,
                description: cdesc,
                address_offset: offset,
                dim,
                registers: inner_regs,
            }));
        }

        peripherals.push(Peripheral {
            name: pname,
            description: pdesc,
            base_address: base_addr,
            group_name,
            interrupts,
            registers: regs,
