            lib.push_str(" } } }\n");

            if config.reexport_interrupt {
                lib.push_str("#[cfg (feature = \"rt\")] pub use cortex_m_rt :: interrupt ;\n");
                lib.push_str("#[cfg (feature = \"rt\")] pub use self :: Interrupt as interrupt ;\n");
            }
        },
        Target::Riscv => {
            // Simplified riscv interrupt handling
            lib.push_str("#[doc = r\"Enumeration of all the interrupts.\"]\n#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt { }\n");
        },
        _ => {
            // none or mips: no interrupt handling
        }
    }

    // Generate peripherals

    for periph in &device.peripherals {
        // Determine type names using ident_formats
        let periph_mod_default = config.ident_formats.get("peripheral_mod").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
        let periph_type_default = config.ident_formats.get("peripheral").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
        let periph_spec_default = config.ident_formats.get("peripheral_spec").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "Spec".to_string()));
        let periph_singleton_default = config.ident_formats.get("peripheral_singleton").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));

        let periph_mod_name = format_ident(&periph.name, &periph_mod_default);
        let periph_type_name = format_ident(&periph.name, &periph_type_default);
        let periph_spec_name = format_ident(&periph.name, &periph_spec_default);
        let periph_singleton_name = format_ident(&periph.name, &periph_singleton_default);

        // For feature gates
        let mut cfg_attrs = String::new();
        if config.feature_group {
            if let Some(ref group) = periph.group_name {
                let group_feat = group.to_lowercase();
                cfg_attrs.push_str(&format!("#[cfg (feature = \"{}\")] ", group_feat));
            }
        }
        if config.feature_peripheral {
            let feat = periph.name.to_lowercase();
            cfg_attrs.push_str(&format!("#[cfg (feature = \"{}\")] ", feat));
        }

        lib.push_str(&format!("{}#[doc = \"{} peripheral\"] pub type {} = crate :: Periph < {} > ; {}pub struct {} ; impl crate :: PeripheralSpec for {} {{ type RB = {} :: RegisterBlock ; const ADDRESS : usize = 0x{:x} ; const NAME : & 'static str = \"{}\" ; }}\n", cfg_attrs, periph.description, periph_type_name, periph_spec_name, cfg_attrs, periph_spec_name, periph_spec_name, periph_mod_name, periph.base_address, periph_type_name));

        lib.push_str(&format!("{}#[doc = \"{} peripheral\"] pub mod {} {{\n", cfg_attrs, periph.description, periph_mod_name));

        // RegisterBlock
        lib.push_str("#[repr (C)]\n#[doc = \"Register block\"] pub struct RegisterBlock { ");

        for rc in &periph.registers {
            match rc {
                RegisterCluster::Register(reg) => {
                    // handle dim
                    let reg_mod_default = config.ident_formats.get("register_mod").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
                    let reg_mod_name = format_ident(&reg.name, &reg_mod_default);
                    if let Some(dim) = reg.dim {
                        if let Some(_) = &reg.dim_index {
                            // For dim with index list like A,B, generate separate fields? Simplified as array if dimIndex is range?
                            // Check if dim_index is like "0-3" => array
                            // For list like "A,B", generate separate fields dataa, datab
                            if reg.dim_index.as_ref().map(|s| s.contains(',')).unwrap_or(false) {
                                // list
                                let indices = reg.dim_index.as_ref().unwrap().split(',').collect::<Vec<_>>();
                                for idx in indices {
                                    let trimmed = idx.trim();
                                    let field_name = format!("{}{}", reg_mod_name, trimmed.to_lowercase());
                                    lib.push_str(&format!("{} : {},", field_name, format_ident(&reg.name.replace("%s", trimmed), &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string())))));
                                }
                            } else {
                                // array
                                lib.push_str(&format!("{} : [{} ; {}] ,", reg_mod_name, format_ident(&reg.name.replace("%s", ""), &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()))), dim));
                            }
                        } else {
                            lib.push_str(&format!("{} : [{} ; {}] ,", reg_mod_name, format_ident(&reg.name.replace("%s", ""), &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()))), dim));
                        }
                    } else {
                        lib.push_str(&format!("{} : {},", reg_mod_name, format_ident(&reg.name, &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string())))));
                    }
                },
                RegisterCluster::Cluster(cluster) => {
                    // For cluster, similar
                    let cluster_mod_default = config.ident_formats.get("cluster_mod").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
                    let cluster_mod_name = format_ident(&cluster.name, &cluster_mod_default);
                    lib.push_str(&format!("{} : {},", cluster_mod_name, cluster_mod_name));
                }
            }
        }

        lib.push_str(" } impl RegisterBlock { ");

        for rc in &periph.registers {
            match rc {
                RegisterCluster::Register(reg) => {
                    let reg_mod_default = config.ident_formats.get("register_mod").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
                    let reg_mod_name = format_ident(&reg.name, &reg_mod_default);
                    let accessor_default = config.ident_formats.get("register_accessor").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
                    let accessor_name = format_ident(&reg.name, &accessor_default);
                    // If dim, generate accessor with index
                    if let Some(dim) = reg.dim {
                        if reg.dim_index.as_ref().map(|s| s.contains(',')).unwrap_or(false) {
                            let indices = reg.dim_index.as_ref().unwrap().split(',').collect::<Vec<_>>();
                            for idx in indices {
                                let trimmed = idx.trim();
                                let field_name = format!("{}{}", reg_mod_name, trimmed.to_lowercase());
                                let acc_name = format!("{}{}", accessor_name, trimmed.to_lowercase());
                                lib.push_str(&format!("#[doc = \"0x{:x} - {}\"]\n#[inline (always)] pub const fn {} (& self) -> & {} {{ & self . {} }}", reg.address_offset, reg.description, acc_name, format_ident(&reg.name.replace("%s", trimmed), &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()))), field_name));
                            }
                        } else {
                            lib.push_str(&format!("#[doc = \"0x{:x}..0x{:x} - {}\"]\n#[inline (always)] pub const fn {} (& self , n : usize) -> & {} {{ & self . {} [n] }} #[doc = \"Iterator for array of:\"]\n#[doc = \"0x{:x}..0x{:x} - {}\"]\n#[inline (always)] pub fn {}_iter (& self) -> impl Iterator < Item = & {} > {{ self . {} . iter () }}", reg.address_offset, reg.address_offset + (dim as u64 * reg.dim_increment.unwrap_or(4)), reg.description, accessor_name, format_ident(&reg.name.replace("%s", ""), &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()))), reg_mod_name, reg.address_offset, reg.address_offset + (dim as u64 * reg.dim_increment.unwrap_or(4)), reg.description, accessor_name, format_ident(&reg.name.replace("%s", ""), &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()))), reg_mod_name));
                        }
                    } else {
                        lib.push_str(&format!("#[doc = \"0x{:02x} - {}\"]\n#[inline (always)] pub const fn {} (& self) -> & {} {{ & self . {} }}", reg.address_offset, reg.description, accessor_name, format_ident(&reg.name, &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()))), reg_mod_name));
                    }
                },
                _ => {}
            }
        }

        lib.push_str(" }\n");

        // Generate register mods

        for rc in &periph.registers {
            match rc {
                RegisterCluster::Register(reg) => {
                    let reg_type_name = format_ident(&reg.name, &config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string())));

                    lib.push_str(&format!("#[doc = \"{} (rw) register accessor: {}\\n\\nYou can [`read`](crate::Reg::read) this register and get [`{}::R`]. You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`]. You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).\\n\\nFor information about available fields see [`mod@{}`] module\"]\n#[doc (alias = \"{}\")] pub type {} = crate :: Reg < {} :: {}Spec > ;\n", reg_type_name, reg.description, reg.name.to_lowercase(), reg.name.to_lowercase(), reg.name.to_lowercase(), reg.name, reg_type_name));

                    lib.push_str(&format!("#[doc = \"{}\"] pub mod {} {{\n", reg.description, reg.name.to_lowercase()));

                    // R and W
                    lib.push_str(&format!("#[doc = \"Register `{}` reader\"] pub type R = crate :: R < {}Spec > ;\n", reg.name, reg_type_name));
                    lib.push_str(&format!("#[doc = \"Register `{}` writer\"] pub type W = crate :: W < {}Spec > ;\n", reg.name, reg_type_name));

                    // Fields
                    for field in &reg.fields {
                        lib.push_str(&format!("#[doc = \"Field `{}` reader - {}\"] pub type {}R = crate :: BitReader ;\n", field.name, field.description, format_ident(&field.name, &config.ident_formats.get("field_reader").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "R".to_string())))));
                        lib.push_str(&format!("#[doc = \"Field `{}` writer - {}\"] pub type {}W < 'a , REG > = crate :: BitWriter < 'a , REG > ;", field.name, field.description, format_ident(&field.name, &config.ident_formats.get("field_writer").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "W".to_string())))));
                    }

                    // Impl R and W for fields
                    if !reg.fields.is_empty() {
                        lib.push_str(" impl R { ");
                        for field in &reg.fields {
                            lib.push_str(&format!("#[doc = \"Bit {} - {}\"]\n#[inline (always)] pub fn {} (& self) -> {}R {{ {}R :: new ((self . bits & {}) != 0) }}", field.bit_offset, field.description, field.name.to_lowercase(), field.name, field.name, 1 << field.bit_offset));
                        }
                        lib.push_str(" } impl W { ");
                        for field in &reg.fields {
                            lib.push_str(&format!("#[doc = \"Bit {} - {}\"]\n#[inline (always)] pub fn {} (& mut self) -> {}W < '_ , {}Spec > {{ {}W :: new (self , {}) }}", field.bit_offset, field.description, field.name.to_lowercase(), field.name, reg_type_name, field.name, field.bit_offset));
                        }
                        lib.push_str(" } ");
                    }

                    // Spec
                    lib.push_str(&format!("#[doc = \"{}\\n\\nYou can [`read`](crate::Reg::read) this register and get [`{}::R`](R). You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`](W). You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).\"] pub struct {}Spec ; impl crate :: RegisterSpec for {}Spec {{ type Ux = u{} ; }}\n", reg.description, reg.name.to_lowercase(), reg.name.to_lowercase(), reg_type_name, reg_type_name, reg.size));

                    lib.push_str(&format!("#[doc = \"`read()` method returns [`{}::R`](R) reader structure\"] impl crate :: Readable for {}Spec {{ }}\n", reg.name.to_lowercase(), reg_type_name));
                    lib.push_str(&format!("#[doc = \"`write(|w| ..)` method takes [`{}::W`](W) writer structure\"] impl crate :: Writable for {}Spec {{ type Safety = crate :: Unsafe ; }}\n", reg.name.to_lowercase(), reg_type_name));
                    lib.push_str(&format!("#[doc = \"`reset()` method sets {} to value 0\"] impl crate :: Resettable for {}Spec {{ }} }}\n", reg.name, reg_type_name));
                },
                _ => {}
            }
        }

        lib.push_str(" }\n");
    }

    // Peripherals struct

    // Determine device peripherals static and Peripherals struct

    let (device_peripherals_attr, steal_impl) = match config.edition {
        Edition::E2021 => (
            "#[no_mangle] static mut DEVICE_PERIPHERALS : bool = false ;\n".to_string(),
            "DEVICE_PERIPHERALS = true ;".to_string()
        ),
        Edition::E2024 => (
            "#[unsafe (no_mangle)] static mut DEVICE_PERIPHERALS : bool = false ;\n".to_string(),
            "unsafe { DEVICE_PERIPHERALS = true }".to_string()
        ),
    };

    lib.push_str(&device_peripherals_attr);
    lib.push_str("#[doc = r\" All the peripherals.\"]\n#[allow (non_snake_case)] pub struct Peripherals {\n");

    for periph in &device.peripherals {
        let periph_singleton_default = config.ident_formats.get("peripheral_singleton").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
        let periph_type_default = config.ident_formats.get("peripheral").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
        let singleton_name = format_ident(&periph.name, &periph_singleton_default);
        let type_name = format_ident(&periph.name, &periph_type_default);

        let mut cfg = String::new();
        if config.feature_group {
            if let Some(ref g) = periph.group_name {
                cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", g.to_lowercase()));
            }
        }
        if config.feature_peripheral {
            cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", periph.name.to_lowercase()));
        }

        lib.push_str(&format!("{}#[doc = \"{}\"] pub {} : {} ,\n", cfg, periph.name, singleton_name, type_name));
    }

    lib.push_str(" } impl Peripherals {\n#[doc = r\" Returns all the peripherals *once*.\"]\n#[cfg (feature = \"critical-section\")]\n#[inline] pub fn take () -> Option < Self > { critical_section :: with (| _ | { if unsafe { DEVICE_PERIPHERALS } { return None } Some (unsafe { Peripherals :: steal () }) }) }\n");

    lib.push_str("#[doc = r\" Unchecked version of `Peripherals::take`.\"]\n#[doc = r\"\"\n]\n#[doc = r\" # Safety\"]\n#[doc = r\"\"\n]\n#[doc = r\" Each of the returned peripherals must be used at most once.\"]\n");

    match config.edition {
        Edition::E2021 => {
            lib.push_str(&format!("#[inline] pub unsafe fn steal () -> Self {{ {} Peripherals {{ ", steal_impl));
            for periph in &device.peripherals {
                let singleton_default = config.ident_formats.get("peripheral_singleton").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
                let type_default = config.ident_formats.get("peripheral").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
                let singleton_name = format_ident(&periph.name, &singleton_default);
                let type_name = format_ident(&periph.name, &type_default);
                let mut cfg = String::new();
                if config.feature_group {
                    if let Some(ref g) = periph.group_name {
                        cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", g.to_lowercase()));
                    }
                }
                if config.feature_peripheral {
                    cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", periph.name.to_lowercase()));
                }
                lib.push_str(&format!("{}{} : {} :: steal () ,", cfg, singleton_name, type_name));
            }
            lib.push_str(" } } }\n");
        },
        Edition::E2024 => {
            lib.push_str("#[inline] pub unsafe fn steal () -> Self { unsafe { DEVICE_PERIPHERALS = true } Peripherals { ");
            for periph in &device.peripherals {
                let singleton_default = config.ident_formats.get("peripheral_singleton").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
                let type_default = config.ident_formats.get("peripheral").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
                let singleton_name = format_ident(&periph.name, &singleton_default);
                let type_name = format_ident(&periph.name, &type_default);
                lib.push_str(&format!("{} : unsafe {{ {} :: steal () }} ,", singleton_name, type_name));
            }
            lib.push_str(" } } }\n");
        }
    }

    // Write lib.rs or mod.rs

    let lib_file_name = if config.make_mod { "mod.rs" } else { "lib.rs" };
    let lib_path = out_dir.join(lib_file_name);
    fs::write(&lib_path, lib).unwrap_or_else(|_| {
        eprintln!("\nthread 'main' panicked at src/main.rs:361:54:");
        eprintln!("Couldn't create output file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}");
        eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        std::process::exit(101);
    });

    // Write build.rs and device.x if needed

    if has_device_x {
        let build_path = out_dir.join("build.rs");
        fs::write(&build_path, build_rs_content).unwrap_or_else(|_| {
            eprintln!("\nthread 'main' panicked at src/main.rs:361:54:");
            eprintln!("Couldn't create output file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}");
            eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
            std::process::exit(101);
        });
        let device_x_path = out_dir.join("device.x");
        fs::write(&device_x_path, device_x_content).unwrap_or_else(|_| {
            eprintln!("\nthread 'main' panicked at src/main.rs:361:54:");
            eprintln!("Couldn't create output file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}");
            eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
            std::process::exit(101);
        });
    }
}
RS
"}

