fn parse_case(s: &str) -> Option<IdentCase> {
    match s {
        "" => Some(IdentCase::Unchanged),
        "p" => Some(IdentCase::Pascal),
        "c" => Some(IdentCase::Constant),
        "s" => Some(IdentCase::Snake),
        _ => None,
    }
}

fn apply_case(original: &str, case: &Option<IdentCase>) -> String {
    match case {
        None => original.to_string(), // interrupt case None
        Some(IdentCase::Unchanged) => original.to_string(),
        Some(IdentCase::Pascal) => {
            // Convert to PascalCase: split by _ or - and capitalize
            // For simplicity, use heck
            use heck::ToPascalCase;
            original.to_pascal_case()
        },
        Some(IdentCase::Constant) => {
            use heck::ToShoutySnakeCase;
            original.to_shouty_snake_case()
        },
        Some(IdentCase::Snake) => {
            use heck::ToSnakeCase;
            original.to_snake_case()
        },
    }
}

fn format_ident(original: &str, fmt: &IdentFormat) -> String {
    let cased = apply_case(original, &fmt.case);
    format!("{}{}{}", fmt.prefix, cased, fmt.suffix)
}

