                                eprintln!("        unknown variant `{}`, expected one of `off`, `error`, `warn`, `info`, `debug`, `trace`", v);
                                std::process::exit(1);
                            }
                            config.log_level = match v.as_str() {
                                "off" => LogLevel::Off,
                                "error" => LogLevel::Error,
                                "warn" => LogLevel::Warn,
                                "info" => LogLevel::Info,
                                "debug" => LogLevel::Debug,
                                "trace" => LogLevel::Trace,
                                _ => LogLevel::Info,
                            };
                        }
                        if let Some(b) = tcfg.reexport_core_peripherals { config.reexport_core_peripherals = b; }
                        if let Some(b) = tcfg.reexport_interrupt { config.reexport_interrupt = b; }
                        if let Some(v) = tcfg.ident_formats_theme {
                            if v == "legacy" {
                                config.ident_formats = legacy_ident_formats();
                                config.ident_formats_theme = Some(v);
                            } else if v == "new" {
                                // new theme also allowed in config? Earlier it failed, but let's allow and set default
                                config.ident_formats = Config::default().ident_formats;
                                config.ident_formats_theme = Some(v);
                            } else {
                                eprintln!("[ERROR svd2rust] Failed to deserialize value");
                                eprintln!("");
                                eprintln!("    Caused by:");
                                eprintln!("        unknown variant `{}`, expected `legacy`", v);
                                std::process::exit(1);
                            }
                        }
                        if let Some(b) = tcfg.field_names_for_enums { config.field_names_for_enums = b; }
                        if let Some(v) = tcfg.base_address_shift { config.base_address_shift = v; }
                        if let Some(s) = tcfg.settings_file { config.settings_file = Some(s); }
                        if let Some(s) = tcfg.interrupt_link_section { config.interrupt_link_section = Some(s); }

                        if let Some(ifs) = tcfg.ident_formats {
                            for (k, v) in ifs {
                                let prefix = v.prefix.unwrap_or_default();
                                let suffix = v.suffix.unwrap_or_default();
                                let case_opt = match v.case.as_deref() {
                                    Some("pascal") => Some(IdentCase::Pascal),
                                    Some("constant") => Some(IdentCase::Constant),
                                    Some("snake") => Some(IdentCase::Snake),
                                    Some("") => Some(IdentCase::Unchanged),
                                    None => Some(IdentCase::Unchanged),
                                    Some(other) => {
                                        eprintln!("[ERROR svd2rust] Failed to deserialize value");
                                        eprintln!("");
                                        eprintln!("    Caused by:");
                                        eprintln!("        unknown variant `{}`, expected one of `constant`, `pascal`, `snake`", other);
                                        std::process::exit(1);
                                    }
                                };
                                config.ident_formats.insert(k, IdentFormat::new(prefix, case_opt, suffix));
                            }
                        }
                    },
                    Err(e) => {
                        eprintln!("[ERROR svd2rust] Failed to parse value for parser #2");
                        eprintln!("");
                        eprintln!("    Caused by:");
                        eprintln!("        0: Failed parse TOML");
                        eprintln!("        1: {}", e);
                        eprintln!("");
                        std::process::exit(1);
                    }
                }
            },
            Err(e) => {
                eprintln!("[ERROR svd2rust] Failed to read config file {}", cfg_path);
                eprintln!("    Caused by: {}", e);
                std::process::exit(1);
            }
        }
    }

    // Apply CLI overrides that were already set but we need to override config

    // We already set some in config defaults and then applied CLI directly for some, but we need to re-apply for those that were parsed before config

    // For simplicity, we already have atomics etc variables from CLI, we will override config with them

    if atomics { config.atomics = true; }
    if let Some(v) = atomics_feature { config.atomics_feature = Some(v); }
    if ignore_groups { config.ignore_groups = true; }
    if keep_list { config.keep_list = true; }
    if generic_mod { config.generic_mod = true; }
    if feature_group { config.feature_group = true; }
    if feature_peripheral { config.feature_peripheral = true; }
    if field_names_for_enums { config.field_names_for_enums = true; }
    if max_cluster_size { config.max_cluster_size = true; }
    if impl_debug { config.impl_debug = true; }
    if let Some(v) = impl_debug_feature { config.impl_debug_feature = Some(v); }
    if let Some(v) = impl_defmt { config.impl_defmt = Some(v); }
    if make_mod { config.make_mod = true; }
    if skip_attrs { config.skip_crate_attributes = true; }
    if strict { config.strict = true; }
    if reexport_core { config.reexport_core_peripherals = true; }
    if reexport_interrupt { config.reexport_interrupt = true; }

    // output_dir handling: CLI overrides config
    let output_dir_str = if let Some(od) = output_dir_cli {
        od
    } else if let Some(od) = config.output_dir.clone() {
        od
    } else {
        ".".to_string()
    };

    // input handling: CLI -i overrides config input, else stdin
    let input_str = if let Some(inp) = input_path {
        Some(inp)
    } else if let Some(inp) = config.input.clone() {
        Some(inp)
    } else {
        None
    };

    // settings file: CLI overrides
    if let Some(sf) = settings_path {
        config.settings_file = Some(sf);
    }

    // ident formats from CLI
    for f_str in ident_format_strs {
        parse_ident_format_arg(&f_str, &mut config.ident_formats);
    }

    // logging: we have log_level in config, but we need to set up logging

    // For log=off, suppress
    // For others, print INFO etc

    // We will implement a simple logger that prints to stderr if level >=

    let log_level = config.log_level.clone();

    // Helper to log
    macro_rules! log_info {
        ($($arg:tt)*) => {
            if !matches!(log_level, LogLevel::Off) {
                // Info level includes info, warn, error
                eprintln!("[INFO  svd2rust] {}", format!($($arg)*));
            }
        }
    }
    macro_rules! log_warn {
        ($($arg:tt)*) => {
            if !matches!(log_level, LogLevel::Off) {
                eprintln!("[WARN  svd2rust] {}", format!($($arg)*));
            }
            if matches!(log_level, LogLevel::Error) {
                // error level still shows warn? Actually error level shows error and warn? Let's check original: for log=error, does it show warn? Probably not. But we can approximate: error shows error only, warn shows warn and error, info shows info, warn, error, etc.
            }
        }
    }
    // Actually we need to respect log levels: off < error < warn < info < debug < trace
    // So info level shows info, warn, error
    // warn shows warn, error
    // error shows error only
    // debug shows debug, info, warn, error
    // trace shows all

    // We'll implement a function
    fn should_log(current: &LogLevel, msg_level: &LogLevel) -> bool {
        let order = |lvl: &LogLevel| match lvl {
            LogLevel::Off => 0,
            LogLevel::Error => 1,
            LogLevel::Warn => 2,
            LogLevel::Info => 3,
            LogLevel::Debug => 4,
            LogLevel::Trace => 5,
        };
        order(msg_level) <= order(current) && order(current) != 0
    }

    // But for simplicity, we will just print INFO if log_level is Info or higher (Debug, Trace)
    // And WARN if Warn or higher

    // Now start processing

    if should_log(&log_level, &LogLevel::Info) {
        eprintln!("[INFO  svd2rust] Parsing device from SVD file");
    }

    // Read input SVD file

    let svd_content: String = if let Some(ref inp) = input_str {
        match fs::read_to_string(inp) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("[ERROR svd2rust] Error reading input file {}", inp);
                eprintln!("    Caused by: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        // Read from stdin
        let mut buf = String::new();
        std::io::stdin().read_to_string(&mut buf).unwrap_or(0);
        buf
    };

    if svd_content.trim().is_empty() {
        eprintln!("[ERROR svd2rust] Error parsing SVD XML file");
        eprintln!("");
        eprintln!("    Caused by:");
        eprintln!("        the document does not have a root node");
        std::process::exit(1);
    }

    // Parse SVD based on source_type

    // For simplicity, we support only XML for now, and for yaml/json we will try to parse as xml first and if fails try json/yaml

    // We will implement a very minimal XML parser for device

    // Define structs for SVD

    #[derive(Debug, Clone)]
    struct Device {
        name: String,
        description: String,
        cpu_nvic_prio_bits: Option<u8>,
        peripherals: Vec<Peripheral>,
    }

    #[derive(Debug, Clone)]
    struct Peripheral {
        name: String,
        description: String,
        base_address: u64,
        group_name: Option<String>,
        interrupts: Vec<Interrupt>,
        registers: Vec<RegisterCluster>,
    }

    #[derive(Debug, Clone)]
    struct Interrupt {
        name: String,
        description: String,
        value: u32,
    }

    #[derive(Debug, Clone)]
    enum RegisterCluster {
        Register(Register),
        Cluster(Cluster),
    }

    #[derive(Debug, Clone)]
    struct Register {
        name: String,
        description: String,
        address_offset: u64,
        size: u32,
        access: String,
        reset_value: u64,
        fields: Vec<Field>,
        dim: Option<u32>,
        dim_increment: Option<u64>,
        dim_index: Option<String>,
    }

    #[derive(Debug, Clone)]
    struct Field {
        name: String,
        description: String,
        bit_offset: u32,
        bit_width: u32,
    }

    #[derive(Debug, Clone)]
    struct Cluster {
        name: String,
        description: String,
        address_offset: u64,
        dim: Option<u32>,
        registers: Vec<Register>,
    }

    // Minimal XML parsing: we will use regex to extract

    fn extract_tag_content(xml: &str, tag: &str) -> Vec<String> {
        let mut res = Vec::new();
        let pattern = format!(r"<{}[^>]*>(.*?)</{}>", tag, tag);
        let re = regex::Regex::new(&pattern).unwrap();
        for cap in re.captures_iter(xml) {
            res.push(cap[1].to_string());
        }
        res
    }

    fn extract_single(xml: &str, tag: &str) -> Option<String> {
        let pattern = format!(r"<{}[^>]*>(.*?)</{}>", tag, tag);
        let re = regex::Regex::new(&pattern).unwrap();
        re.captures(xml).map(|c| c[1].trim().to_string())
    }

    // Parse device

    let device_name = extract_single(&svd_content, "name").unwrap_or_else(|| "DEVICE".to_string());
    let device_desc = extract_single(&svd_content, "description").unwrap_or_default();

    // cpu nvicPrioBits
    let cpu_block = extract_single(&svd_content, "cpu").unwrap_or_default();
    let nvic_bits = if cpu_block.contains("nvicPrioBits") {
        let pattern = r"<nvicPrioBits[^>]*>(\d+)</nvicPrioBits>";
        let re = regex::Regex::new(pattern).unwrap();
        re.captures(&cpu_block).and_then(|c| c[1].parse::<u8>().ok())
    } else {
        // try directly in whole file for <nvicPrioBits>
        let pattern = r"<nvicPrioBits[^>]*>(\d+)</nvicPrioBits>";
        let re = regex::Regex::new(pattern).unwrap();
        re.captures(&svd_content).and_then(|c| c[1].parse::<u8>().ok())
    };

    // peripherals
    let peripherals_block = {
        // find <peripherals> ... </peripherals>
        let re = regex::Regex::new(r"<peripherals[^>]*>(?s)(.*?)</peripherals>").unwrap();
        re.captures(&svd_content).map(|c| c[1].to_string()).unwrap_or_default()
    };

    // split peripherals by <peripheral> tags
    let mut peripherals: Vec<Peripheral> = Vec::new();
    let re_periph = regex::Regex::new(r"<peripheral[^>]*>(?s)(.*?)</peripheral>").unwrap();
    for cap in re_periph.captures_iter(&peripherals_block) {
        let periph_xml = &cap[1];
        let pname = extract_single(periph_xml, "name").unwrap_or_else(|| "PERIPH".to_string());
        let pdesc = extract_single(periph_xml, "description").unwrap_or_else(|| format!("{} peripheral", pname));
        let base_str = extract_single(periph_xml, "baseAddress").unwrap_or_else(|| "0".to_string());
        let base_addr = if base_str.starts_with("0x") || base_str.starts_with("0X") {
            u64::from_str_radix(base_str.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
        } else {
            base_str.parse::<u64>().unwrap_or(0)
        };
        let base_addr = base_addr + config.base_address_shift;

        let group_name = extract_single(periph_xml, "groupName");

        // interrupts
        let mut interrupts = Vec::new();
        let re_int = regex::Regex::new(r"<interrupt[^>]*>(?s)(.*?)</interrupt>").unwrap();
        for icap in re_int.captures_iter(periph_xml) {
            let int_xml = &icap[1];
            let iname = extract_single(int_xml, "name").unwrap_or_else(|| "IRQ".to_string());
            let idesc = extract_single(int_xml, "description").unwrap_or_default();
            let ival_str = extract_single(int_xml, "value").unwrap_or_else(|| "0".to_string());
            let ival = ival_str.parse::<u32>().unwrap_or(0);
            interrupts.push(Interrupt { name: iname, description: idesc, value: ival });
        }

        // registers
        let registers_block = {
            let re = regex::Regex::new(r"<registers[^>]*>(?s)(.*?)</registers>").unwrap();
            re.captures(periph_xml).map(|c| c[1].to_string()).unwrap_or_default()
        };

        let mut regs: Vec<RegisterCluster> = Vec::new();

        // For simplicity, only parse <register> tags directly, ignoring clusters for now, but we can parse clusters as well

        let re_reg = regex::Regex::new(r"<register[^>]*>(?s)(.*?)</register>").unwrap();
        for rcap in re_reg.captures_iter(&registers_block) {
            let reg_xml = &rcap[1];
            // Check if dim
            let dim = extract_single(reg_xml, "dim").and_then(|s| s.parse::<u32>().ok());
            let dim_inc_str = extract_single(reg_xml, "dimIncrement");
            let dim_inc = dim_inc_str.map(|s| {
                let s = s.trim();
                if s.starts_with("0x") || s.starts_with("0X") {
                    u64::from_str_radix(s.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
                } else {
                    s.parse::<u64>().unwrap_or(0)
                }
            });
            let dim_index = extract_single(reg_xml, "dimIndex");

            let rname = extract_single(reg_xml, "name").unwrap_or_else(|| "REG".to_string());
            let rdesc = extract_single(reg_xml, "description").unwrap_or_else(|| "".to_string());
            let offset_str = extract_single(reg_xml, "addressOffset").unwrap_or_else(|| "0".to_string());
            let offset = if offset_str.starts_with("0x") || offset_str.starts_with("0X") {
                u64::from_str_radix(offset_str.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
            } else {
                offset_str.parse::<u64>().unwrap_or(0)
            };
            let size_str = extract_single(reg_xml, "size").unwrap_or_else(|| "32".to_string());
            let size = size_str.parse::<u32>().unwrap_or(32);
            let access = extract_single(reg_xml, "access").unwrap_or_else(|| "read-write".to_string());
            let reset_str = extract_single(reg_xml, "resetValue").unwrap_or_else(|| "0".to_string());
            let reset = if reset_str.starts_with("0x") || reset_str.starts_with("0X") {
                u64::from_str_radix(reset_str.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
            } else {
                reset_str.parse::<u64>().unwrap_or(0)
            };

            // fields
            let mut fields = Vec::new();
            let fields_block = {
                let re = regex::Regex::new(r"<fields[^>]*>(?s)(.*?)</fields>").unwrap();
                re.captures(reg_xml).map(|c| c[1].to_string()).unwrap_or_default()
            };
            let re_field = regex::Regex::new(r"<field[^>]*>(?s)(.*?)</field>").unwrap();
