                let field_xml = &fcap[1];
                let fname = extract_single(field_xml, "name").unwrap_or_else(|| "FIELD".to_string());
                let fdesc = extract_single(field_xml, "description").unwrap_or_default();
                let offset_str = extract_single(field_xml, "bitOffset").unwrap_or_else(|| "0".to_string());
                let bit_offset = offset_str.parse::<u32>().unwrap_or(0);
                let width_str = extract_single(field_xml, "bitWidth").unwrap_or_else(|| "1".to_string());
                let bit_width = width_str.parse::<u32>().unwrap_or(1);
                fields.push(Field { name: fname, description: fdesc, bit_offset, bit_width });
            }

            regs.push(RegisterCluster::Register(Register {
                name: rname,
                description: rdesc,
                address_offset: offset,
                size,
                access,
                reset_value: reset,
                fields,
                dim,
                dim_increment: dim_inc,
                dim_index,
            }));
        }

        // clusters: parse <cluster> simple
        let re_cluster = regex::Regex::new(r"<cluster[^>]*>(?s)(.*?)</cluster>").unwrap();
