            let cl_xml = &ccap[1];
            let cname = extract_single(cl_xml, "name").unwrap_or_else(|| "CLUSTER".to_string());
            let cdesc = extract_single(cl_xml, "description").unwrap_or_default();
            let offset_str = extract_single(cl_xml, "addressOffset").unwrap_or_else(|| "0".to_string());
            let offset = if offset_str.starts_with("0x") || offset_str.starts_with("0X") {
