                let reg_xml = &rcap[1];
                let rname = extract_single(reg_xml, "name").unwrap_or_else(|| "REG".to_string());
                let rdesc = extract_single(reg_xml, "description").unwrap_or_default();
                let offset_str = extract_single(reg_xml, "addressOffset").unwrap_or_else(|| "0".to_string());
