    m.insert("register_spec".to_string(), IdentFormat::new("".to_string(), Some(IdentCase::Constant), "_SPEC".to_string()));
    m.insert("field_reader".to_string(), IdentFormat::new("".to_string(), Some(IdentCase::Constant), "_R".to_string()));
