            },
            "-o" | "--output-dir" => {
                if i+1 < args.len() { output_dir_cli = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "-c" | "--config" => {
                if i+1 < args.len() { config_path = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--settings" => {
                if i+1 < args.len() { settings_path = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--edition" => {
                if i+1 < args.len() { edition_str = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--target" => {
                if i+1 < args.len() { target_str = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--atomics" => { atomics = true; i+=1; },
            "--atomics-feature" => {
                if i+1 < args.len() { atomics_feature = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--ignore-groups" => { ignore_groups = true; i+=1; },
            "--keep-list" => { keep_list = true; i+=1; },
            "-g" | "--generic-mod" => { generic_mod_flag = true; i+=1; },
            "--feature-group" => { feature_group = true; i+=1; },
            "--feature-peripheral" => { feature_peripheral = true; i+=1; },
            "-f" | "--ident-format" => {
                if i+1 < args.len() { ident_format_strs.push(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--ident-formats-theme" => {
                if i+1 < args.len() { theme_str = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--field-names-for-enums" => { field_names_for_enums = true; i+=1; },
            "--max-cluster-size" => { max_cluster_size = true; i+=1; },
            "--impl-debug" => { impl_debug = true; i+=1; },
            "--impl-debug-feature" => {
                if i+1 < args.len() { impl_debug_feature = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--impl-defmt" => {
                if i+1 < args.len() { impl_defmt = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "-m" | "--make-mod" => { make_mod = true; i+=1; },
            "--skip-crate-attributes" => { skip_attrs = true; i+=1; },
            "-s" | "--strict" => { strict = true; i+=1; },
            "--source-type" => {
                if i+1 < args.len() { source_type_str = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "--reexport-core-peripherals" => { reexport_core = true; i+=1; },
            "--reexport-interrupt" => { reexport_interrupt = true; i+=1; },
            "-b" | "--base-address-shift" => {
                if i+1 < args.len() { base_shift_str = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            "-l" | "--log" => {
                if i+1 < args.len() { log_level_str = Some(args[i+1].clone()); i+=2; } else { i+=1; }
            },
            _ => {
