            _ => {
                eprintln!("[ERROR svd2rust] Failed to deserialize value");
                eprintln!("");
                eprintln!("    Caused by:");
                eprintln!("        unknown variant `{}`, expected one of `xml`, `yaml`, `json`", src);
                std::process::exit(1);
            }
        }
    }
    if let Some(ref th) = theme_str {
        if th == "legacy" {
            config.ident_formats = legacy_ident_formats();
            config.ident_formats_theme = Some(th.clone());
        } else {
            eprintln!("[ERROR svd2rust] Failed to deserialize value");
            eprintln!("");
            eprintln!("    Caused by:");
            eprintln!("        unknown variant `{}`, expected `legacy`", th);
            std::process::exit(1);
        }
    }
    if let Some(ref bs) = base_shift_str {
        let parsed = if bs.starts_with("0x") || bs.starts_with("0X") {
            u64::from_str_radix(&bs[2..], 16)
        } else {
            bs.parse::<u64>()
        };
        match parsed {
            Ok(v) => config.base_address_shift = v,
            Err(_) => {
                eprintln!("[ERROR svd2rust] Failed to deserialize value");
                eprintln!("");
                eprintln!("    Caused by:");
                eprintln!("        invalid type: string \"{}\", expected u64", bs);
                std::process::exit(1);
            }
        }
    }

    if let Some(ref cfg_path) = config_path {
        match fs::read_to_string(cfg_path) {
            Ok(content) => {
