                }
                #[derive(serde::Deserialize, Debug, Default)]
                struct TomlIdentFormat {
                    prefix: Option<String>,
                    suffix: Option<String>,
                    case: Option<String>,
                }
                #[derive(serde::Deserialize, Debug, Default)]
                struct TomlConfig {
                    target: Option<String>,
