                        if let Some(b) = tcfg.atomics { config.atomics = b; }
                        if let Some(s) = tcfg.atomics_feature { config.atomics_feature = Some(s); }
                        if let Some(b) = tcfg.generic_mod { config.generic_mod = b; }
                        if let Some(b) = tcfg.make_mod { config.make_mod = b; }
                        if let Some(b) = tcfg.skip_crate_attributes { config.skip_crate_attributes = b; }
                        if let Some(b) = tcfg.ignore_groups { config.ignore_groups = b; }
