                        }
                    },
                    Err(e) => {
                        eprintln!("[ERROR svd2rust] Failed to parse value for parser #2");
                        eprintln!("");
                        eprintln!("    Caused by:");
                        eprintln!("        0: Failed parse TOML");
                        eprintln!("        1: {}", e);
                        eprintln!("");
                        std::process::exit(1);
                    }
                }
            },
            Err(e) => {
                eprintln!("[ERROR svd2rust] Failed to read config file {}", cfg_path);
                eprintln!("    Caused by: {}", e);
                std::process::exit(1);
