    m.insert("peripheral".to_string(), IdentFormat::new("".to_string(), Some(IdentCase::Constant), "".to_string()));
    m.insert("enum_value".to_string(), IdentFormat::new("".to_string(), Some(IdentCase::Constant), "".to_string()));
    m.insert("cluster_mod".to_string(), IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
    m.insert("cluster".to_string(), IdentFormat::new("".to_string(), Some(IdentCase::Constant), "".to_string()));
    m
}
fn apply_case(original: &str, case: &Option<IdentCase>) -> String {
    match case {
        None => original.to_string(),
        Some(IdentCase::Unchanged) => original.to_string(),
        Some(IdentCase::Pascal) => { use heck::ToPascalCase; original.to_pascal_case() },
        Some(IdentCase::Constant) => { use heck::ToShoutySnakeCase; original.to_shouty_snake_case() },
        Some(IdentCase::Snake) => { use heck::ToSnakeCase; original.to_snake_case() },
    }
}
fn format_ident(original: &str, fmt: &IdentFormat) -> String {
    let cased = apply_case(original, &fmt.case);
    format!("{}{}{}", fmt.prefix, cased, fmt.suffix)
}
fn parse_ident_format_arg(s: &str, formats: &mut IdentFormats) {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() < 4 {
        if parts.len() == 3 {
            let typ = parts[0];
            let prefix = parts[1];
            let suffix = parts[2];
            if prefix.is_empty() { return; }
            let fmt = IdentFormat::new(prefix.to_string(), Some(IdentCase::Unchanged), suffix.to_string());
            formats.insert(typ.to_string(), fmt);
        }
        return;
    }
    let typ = parts[0];
    let prefix = parts[1];
    let case_str = parts[2];
    let suffix = parts[3];
    let case_opt = match case_str {
        "" => Some(IdentCase::Unchanged),
        "p" => Some(IdentCase::Pascal),
        "c" => Some(IdentCase::Constant),
        "s" => Some(IdentCase::Snake),
        _ => return,
    };
    let allowed = ["field_accessor","cluster","register_spec","field_reader","peripheral_feature","peripheral_singleton","enum_value","enum_write_name","peripheral_mod","cluster_mod","register_accessor","enum_value_accessor","interrupt","peripheral","peripheral_spec","register_mod","enum_name","enum_read_name","field_writer","register","cluster_accessor"];
    if !allowed.contains(&typ) { return; }
    let fmt = IdentFormat::new(prefix.to_string(), case_opt, suffix.to_string());
    formats.insert(typ.to_string(), fmt);
}
fn should_log(current: &LogLevel, msg_level: &LogLevel) -> bool {
    let order = |lvl: &LogLevel| match lvl {
        LogLevel::Off => 0,
        LogLevel::Error => 1,
        LogLevel::Warn => 2,
        LogLevel::Info => 3,
        LogLevel::Debug => 4,
        LogLevel::Trace => 5,
    };
    order(msg_level) <= order(current) && order(current) != 0
}

fn format_address(addr: u64) -> String {
    // Format with underscores: group hex digits in 4, lower?
    // Example: 0x40000000 -> 0x4000_0000
    // 0x12345678 -> 0x1234_5678
    // For address < 0x10000 maybe without underscore?
    let hex = format!("{:x}", addr);
    if hex.len() <= 4 {
        format!("0x{}", hex)
    } else {
        // insert underscore every 4 from right? Original groups every 4?
        // For 8 digits, split into 4 and 4.
        let mut out = String::new();
        let mut chars: Vec<char> = hex.chars().collect();
        // Pad to multiple of 4? For 0x40000000, hex is 8 chars, split as 4,4 => 4000_0000
        // For 0x12345678 => 1234_5678
        // For 0x40001000 => 4000_1000
        // For 0x40000000+shift: e.g., 0x40000000+0x1000=0x40001000 => 4000_1000
        // Implementation: if len >4, insert '_' at len-4
        if hex.len() > 4 {
            let split_at = hex.len() - 4;
            out.push_str(&hex[..split_at]);
            out.push('_');
            out.push_str(&hex[split_at..]);
        } else {
            out = hex;
        }
        format!("0x{}", out)
    }
}

