                        if let Some(s) = tcfg.impl_debug_feature { config.impl_debug_feature = Some(s); }
                        if let Some(s) = tcfg.impl_defmt { config.impl_defmt = Some(s); }
                        if let Some(s) = tcfg.output_dir { if config.output_dir.is_none() && output_dir_cli.is_none() { config.output_dir = Some(s); } }
                        if let Some(s) = tcfg.input { if input_path.is_none() { config.input = Some(s); } }
                        if let Some(v) = tcfg.source_type {
                            match v.as_str() {
                                "xml" => config.source_type = SourceType::Xml,
