                                "json" => config.source_type = SourceType::Json,
                                _ => {
                                    eprintln!("[ERROR svd2rust] Failed to deserialize value\n\n    Caused by:\n        unknown variant `{}`, expected one of `xml`, `yaml`, `json`", v);
                                    std::process::exit(1);
                                }
                            }
