    };

    if svd_content.trim().is_empty() {
        eprintln!("[ERROR svd2rust] Error parsing SVD XML file\n\n    Caused by:\n        the document does not have a root node");
        std::process::exit(1);
    }

    #[derive(Debug, Clone)]
    struct Device { name: String, cpu_nvic: Option<u8>, peripherals: Vec<Peripheral>, }
    #[derive(Debug, Clone)]
    struct Peripheral { name: String, description: String, base_address: u64, group_name: Option<String>, interrupts: Vec<Interrupt>, registers: Vec<RegInfo>, }
    #[derive(Debug, Clone)]
    struct Interrupt { name: String, description: String, value: u32 }
    #[derive(Debug, Clone)]
    struct RegInfo { name: String, description: String, offset: u64, size: u32, fields: Vec<FieldInfo>, dim: Option<u32>, dim_inc: Option<u64>, dim_index: Option<String>, }
    #[derive(Debug, Clone)]
    struct FieldInfo { name: String, description: String, bit_offset: u32 }

    fn extract_single(xml: &str, tag: &str) -> Option<String> {
        let pattern = format!(r"<{}[^>]*>(.*?)</{}>", tag, tag);
        let re = regex::Regex::new(&pattern).unwrap();
        re.captures(xml).map(|c| c[1].trim().to_string())
    }

    let device_name = extract_single(&svd_content, "name").unwrap_or_else(|| "DEVICE".to_string());
    let cpu_block = extract_single(&svd_content, "cpu").unwrap_or_default();
    let nvic_bits = {
        let re = regex::Regex::new(r"<nvicPrioBits[^>]*>(\d+)</nvicPrioBits>").unwrap();
        re.captures(&cpu_block).and_then(|c| c[1].parse::<u8>().ok()).or_else(|| {
            re.captures(&svd_content).and_then(|c| c[1].parse::<u8>().ok())
        })
    };

    let periph_block_re = regex::Regex::new(r"<peripherals[^>]*>(?s)(.*?)</peripherals>").unwrap();
    let peripherals_block = periph_block_re.captures(&svd_content).map(|c| c[1].to_string()).unwrap_or_default();
    let re_periph = regex::Regex::new(r"<peripheral[^>]*>(?s)(.*?)</peripheral>").unwrap();
    let mut peripherals = Vec::new();
    for cap in re_periph.captures_iter(&peripherals_block) {
        let periph_xml = &cap[1];
        let pname = extract_single(periph_xml, "name").unwrap_or_else(|| "PERIPH".to_string());
        let pdesc = extract_single(periph_xml, "description").unwrap_or_else(|| format!("{} peripheral", pname));
        let base_str = extract_single(periph_xml, "baseAddress").unwrap_or_else(|| "0".to_string());
        let base_addr = if base_str.trim().starts_with("0x") || base_str.trim().starts_with("0X") {
            u64::from_str_radix(base_str.trim().trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0)
        } else { base_str.trim().parse::<u64>().unwrap_or(0) } + config.base_address_shift;
        let group_name = extract_single(periph_xml, "groupName");
        let mut interrupts = Vec::new();
        let re_int = regex::Regex::new(r"<interrupt[^>]*>(?s)(.*?)</interrupt>").unwrap();
        for icap in re_int.captures_iter(periph_xml) {
            let int_xml = &icap[1];
            let iname = extract_single(int_xml, "name").unwrap_or_else(|| "IRQ".to_string());
            let idesc = extract_single(int_xml, "description").unwrap_or_default();
            let ival = extract_single(int_xml, "value").and_then(|s| s.parse::<u32>().ok()).unwrap_or(0);
            interrupts.push(Interrupt{ name: iname, description: idesc, value: ival });
        }
        let regs_block_re = regex::Regex::new(r"<registers[^>]*>(?s)(.*?)</registers>").unwrap();
        let registers_block = regs_block_re.captures(periph_xml).map(|c| c[1].to_string()).unwrap_or_default();
        let re_reg = regex::Regex::new(r"<register[^>]*>(?s)(.*?)</register>").unwrap();
        let mut regs = Vec::new();
        for rcap in re_reg.captures_iter(&registers_block) {
            let reg_xml = &rcap[1];
            let dim = extract_single(reg_xml, "dim").and_then(|s| s.parse::<u32>().ok());
            let dim_inc = extract_single(reg_xml, "dimIncrement").map(|s| {
                let s = s.trim();
                if s.starts_with("0x") || s.starts_with("0X") { u64::from_str_radix(s.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0) } else { s.parse::<u64>().unwrap_or(0) }
            });
            let dim_index = extract_single(reg_xml, "dimIndex");
            let rname = extract_single(reg_xml, "name").unwrap_or_else(|| "REG".to_string());
            let rdesc = extract_single(reg_xml, "description").unwrap_or_default();
            let offset = extract_single(reg_xml, "addressOffset").map(|s| {
                let s = s.trim();
                if s.starts_with("0x") || s.starts_with("0X") { u64::from_str_radix(s.trim_start_matches("0x").trim_start_matches("0X"), 16).unwrap_or(0) } else { s.parse::<u64>().unwrap_or(0) }
            }).unwrap_or(0);
            let size = extract_single(reg_xml, "size").and_then(|s| s.parse::<u32>().ok()).unwrap_or(32);
            let mut fields = Vec::new();
            let fields_block_re = regex::Regex::new(r"<fields[^>]*>(?s)(.*?)</fields>").unwrap();
            let fields_block = fields_block_re.captures(reg_xml).map(|c| c[1].to_string()).unwrap_or_default();
            let re_field = regex::Regex::new(r"<field[^>]*>(?s)(.*?)</field>").unwrap();
            for fcap in re_field.captures_iter(&fields_block) {
                let field_xml = &fcap[1];
                let fname = extract_single(field_xml, "name").unwrap_or_else(|| "FIELD".to_string());
                let fdesc = extract_single(field_xml, "description").unwrap_or_default();
                let bit_offset = extract_single(field_xml, "bitOffset").and_then(|s| s.parse::<u32>().ok()).unwrap_or(0);
                fields.push(FieldInfo{ name: fname, description: fdesc, bit_offset });
            }
            regs.push(RegInfo{ name: rname, description: rdesc, offset, size, fields, dim, dim_inc, dim_index });
        }
        peripherals.push(Peripheral{ name: pname, description: pdesc, base_address: base_addr, group_name, interrupts, registers: regs });
    }

    let device = Device{ name: device_name, cpu_nvic: nvic_bits, peripherals };

    if should_log(&log_level, &LogLevel::Info) { eprintln!("[INFO  svd2rust] Rendering device"); }

    let out_dir = PathBuf::from(output_dir_str);
    if !out_dir.exists() {
        eprintln!("\nthread 'main' panicked at src/main.rs:361:54:");
        eprintln!("Couldn't create output file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}");
        eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        std::process::exit(101);
    }

    let has_device_x = matches!(config.target, Target::CortexM | Target::Msp430 | Target::Riscv | Target::XtensaLx);
    let build_rs_content = "# ! [doc = r\" Builder file for Peripheral access crate generated by svd2rust tool\"] use std :: env ; use std :: fs :: File ; use std :: io :: Write ; use std :: path :: PathBuf ; fn main () { if env :: var_os (\"CARGO_FEATURE_RT\") . is_some () { let out = & PathBuf :: from (env :: var_os (\"OUT_DIR\") . unwrap ()) ; File :: create (out . join (\"device.x\")) . unwrap () . write_all (include_bytes ! (\"device.x\")) . unwrap () ; println ! (\"cargo:rustc-link-search={}\" , out . display ()) ; println ! (\"cargo:rerun-if-changed=device.x\") ; } println ! (\"cargo:rerun-if-changed=build.rs\") ; }\n";

    let mut device_x_content = String::new();
    if has_device_x {
        let mut all_ints = Vec::new();
        for p in &device.peripherals { for i in &p.interrupts { all_ints.push(i); } }
        if all_ints.is_empty() {
            device_x_content = "\n".to_string();
        } else {
            for int in all_ints { device_x_content.push_str(&format!("PROVIDE({} = DefaultHandler);\n", int.name)); }
            device_x_content.push_str("\n");
        }
    }

    if config.feature_group || config.feature_peripheral {
        let mut toml = String::new();
        toml.push_str("# Below are the FEATURES generated by svd2rust base on groupName in SVD file.\n# Please copy them to Cargo.toml.\n[features]\n");
        if config.feature_group {
            let mut groups: Vec<String> = Vec::new();
            for p in &device.peripherals { if let Some(ref g) = p.group_name { let l = g.to_lowercase(); if !groups.contains(&l) { groups.push(l); } } }
            if groups.is_empty() {
                toml.push_str("all-groups = []\n");
            } else {
                for g in &groups { toml.push_str(&format!("{} = []\n", g)); }
                let joined = groups.iter().map(|g| format!("\"{}\"", g)).collect::<Vec<_>>().join(",");
                toml.push_str(&format!("all-groups = [{}]\n", joined));
            }
            if config.feature_peripheral {
                let mut periph_names = Vec::new();
                for p in &device.peripherals { let l = p.name.to_lowercase(); if !periph_names.contains(&l) { periph_names.push(l); } }
                for pn in &periph_names { toml.push_str(&format!("{} = []\n", pn)); }
                let joined = periph_names.iter().map(|n| format!("\"{}\"", n)).collect::<Vec<_>>().join(",");
                toml.push_str(&format!("all-peripherals = [{}]\n", joined));
            }
        } else if config.feature_peripheral {
            let mut periph_names = Vec::new();
            for p in &device.peripherals { let l = p.name.to_lowercase(); if !periph_names.contains(&l) { periph_names.push(l); } }
            for pn in &periph_names { toml.push_str(&format!("{} = []\n", pn)); }
            let joined = periph_names.iter().map(|n| format!("\"{}\"", n)).collect::<Vec<_>>().join(",");
            toml.push_str(&format!("all-peripherals = [{}]\n", joined));
        }
        let _ = fs::write(out_dir.join("features.toml"), toml);
    }

    let generic_plain = include_str!("generic_plain.rs");
    let generic_atomics = include_str!("generic_atomics.rs");
    let inline_plain = include_str!("inline_generic_plain.rs");
    let inline_atomics = include_str!("inline_generic_atomics.rs");
    let inline_atomics_feat = include_str!("inline_generic_atomics_feat.rs");

    let generic_content = if config.atomics { generic_atomics } else { generic_plain };
    let inline_content = if config.atomics {
        if let Some(ref feat) = config.atomics_feature {
            // For feature gated atomics, we need to include cfg
            inline_atomics_feat.replace("myfeat", feat)
        } else {
            inline_atomics.to_string()
        }
    } else {
        inline_plain.to_string()
    };

    if config.generic_mod {
        let _ = fs::write(out_dir.join("generic.rs"), generic_content);
    }

    let mut lib = String::new();
    if !config.skip_crate_attributes {
        if !config.make_mod {
            lib.push_str(&format!("# ! [doc = \"Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (63c65c2 2026-06-11))\\n\\nYou can find an overview of the generated API [here].\\n\\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n[repository]: https://github.com/rust-embedded/svd2rust\"] # ! [allow (non_camel_case_types)] # ! [allow (non_snake_case)] # ! [no_std] # ! [cfg_attr (docsrs , feature (doc_cfg))]\n", device.name));
        } else {
            lib.push_str(&format!("# ! [doc = \"Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (63c65c2 2026-06-11))\\n\\nYou can find an overview of the generated API [here].\\n\\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n[repository]: https://github.com/rust-embedded/svd2rust\"]\n", device.name));
        }
    }

    if let Target::CortexM = config.target {
        if let Some(bits) = device.cpu_nvic {
            lib.push_str(&format!("#[doc = r\"Number available in the NVIC for configuring priority\"] pub const NVIC_PRIO_BITS : u8 = {} ;\n", bits));
        }
    }
    if config.reexport_core_peripherals {
        if let Target::CortexM = config.target {
            lib.push_str("pub use cortex_m :: peripheral :: Peripherals as CorePeripherals ; pub use cortex_m :: peripheral :: { CBP , CPUID , DCB , DWT , FPB , ITM , MPU , NVIC , SCB , SYST , TPIU , } ;\n");
        }
    }

    lib.push_str("#[allow (unused_imports)] use generic :: * ;\n");
    if config.generic_mod {
        lib.push_str("#[doc = r\"Common register and bit access and modify traits\"] pub mod generic ;\n");
    } else {
        lib.push_str(&inline_content);
        lib.push_str("\n");
    }

    let mut max_int = 0;
    let mut has_int = false;
    for p in &device.peripherals { for i in &p.interrupts { has_int = true; if i.value > max_int { max_int = i.value; } } }

    match config.target {
        Target::CortexM | Target::Msp430 | Target::XtensaLx => {
            let link_section = config.interrupt_link_section.clone().unwrap_or_else(|| ".vector_table.interrupts".to_string());
            let (link_attr, no_mangle, extern_c) = match config.edition {
                Edition::E2021 => (format!("#[link_section = \"{}\"]", link_section), "#[no_mangle]".to_string(), "#[cfg (feature = \"rt\")] extern \"C\" { }".to_string()),
                Edition::E2024 => (format!("#[unsafe (link_section = \"{}\")]", link_section), "#[unsafe (no_mangle)]".to_string(), "#[cfg (feature = \"rt\")] unsafe extern \"C\" { }".to_string()),
            };
            lib.push_str(&format!("{} \n", extern_c));
            lib.push_str("#[doc (hidden)]\n#[repr (C)] pub union Vector { _handler : unsafe extern \"C\" fn () , _reserved : u32 , }\n");
            lib.push_str("#[cfg (feature = \"rt\")]\n#[doc (hidden)]\n");
            if has_int {
                lib.push_str(&format!("{} \n{} pub static __INTERRUPTS : [Vector ; {}] = [", link_attr, no_mangle, max_int+1));
                let mut by_val: HashMap<u32, String> = HashMap::new();
                for p in &device.peripherals { for intr in &p.interrupts { by_val.insert(intr.value, intr.name.clone()); } }
                for i in 0..=max_int {
                    if let Some(name) = by_val.get(&i) {
                        lib.push_str(&format!("Vector {{ _handler : {} }},", name));
                    } else {
                        lib.push_str("Vector { _reserved : 0 },");
                    }
                }
                lib.push_str("] ;\n");
            } else {
                lib.push_str(&format!("{} \n{} pub static __INTERRUPTS : [Vector ; 0] = [] ;\n", link_attr, no_mangle));
            }
            lib.push_str("#[doc = r\"Enumeration of all the interrupts.\"]\n#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt { ");
            for p in &device.peripherals { for intr in &p.interrupts { lib.push_str(&format!("#[doc = \"{} - {}\"] {} = {} ,", intr.value, intr.description, intr.name, intr.value)); } }
            lib.push_str(" } unsafe impl cortex_m :: interrupt :: InterruptNumber for Interrupt {\n#[inline (always)] fn number (self) -> u16 { match self { ");
            for p in &device.peripherals { for intr in &p.interrupts { lib.push_str(&format!("Interrupt :: {} => {} ,", intr.name, intr.value)); } }
            lib.push_str(" } } }\n");
            if config.reexport_interrupt {
                lib.push_str("#[cfg (feature = \"rt\")] pub use cortex_m_rt :: interrupt ;\n#[cfg (feature = \"rt\")] pub use self :: Interrupt as interrupt ;\n");
            }
        },
        Target::Riscv => {
            lib.push_str("#[doc = r\"Enumeration of all the interrupts.\"]\n#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt { }\n");
        },
        _ => {}
    }

    for periph in &device.peripherals {
        let periph_mod_fmt = config.ident_formats.get("peripheral_mod").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
        let periph_type_fmt = config.ident_formats.get("peripheral").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
        let periph_spec_fmt = config.ident_formats.get("peripheral_spec").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "Spec".to_string()));
        let periph_singleton_fmt = config.ident_formats.get("peripheral_singleton").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));

        let periph_mod_name = format_ident(&periph.name, &periph_mod_fmt);
        let periph_type_name = format_ident(&periph.name, &periph_type_fmt);
        let periph_spec_name = format_ident(&periph.name, &periph_spec_fmt);
        let singleton_name = format_ident(&periph.name, &periph_singleton_fmt);

        let mut cfg = String::new();
        if config.feature_group { if let Some(ref g) = periph.group_name { cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", g.to_lowercase())); } }
        if config.feature_peripheral { cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", periph.name.to_lowercase())); }

        lib.push_str(&format!("{}#[doc = \"{} peripheral\"] pub type {} = crate :: Periph < {} > ; {}pub struct {} ; impl crate :: PeripheralSpec for {} {{ type RB = {} :: RegisterBlock ; const ADDRESS : usize = {} ; const NAME : & 'static str = \"{}\" ; }}\n", cfg, periph.description, periph_type_name, periph_spec_name, cfg, periph_spec_name, periph_spec_name, periph_mod_name, format_address(periph.base_address), periph_type_name));
        lib.push_str(&format!("{}#[doc = \"{} peripheral\"] pub mod {} {{\n", cfg, periph.description, periph_mod_name));
        lib.push_str("#[repr (C)]\n#[doc = \"Register block\"] pub struct RegisterBlock { ");

        for reg in &periph.registers {
            let reg_mod_fmt = config.ident_formats.get("register_mod").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
            let reg_type_fmt = config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
            let reg_mod_name = format_ident(&reg.name, &reg_mod_fmt);
            let reg_type_name = format_ident(&reg.name.replace("%s",""), &reg_type_fmt);
            if let Some(dim) = reg.dim {
                if reg.dim_index.as_ref().map(|s| s.contains(',')).unwrap_or(false) {
                    let indices: Vec<&str> = reg.dim_index.as_ref().unwrap().split(',').collect();
                    for idx in indices {
                        let trimmed = idx.trim();
                        let fname = format!("{}{}", reg_mod_name, trimmed.to_lowercase());
                        let tname = format_ident(&reg.name.replace("%s", trimmed), &reg_type_fmt);
                        lib.push_str(&format!("{} : {},", fname, tname));
                    }
                } else {
                    lib.push_str(&format!("{} : [{} ; {}] ,", reg_mod_name, reg_type_name, dim));
                }
            } else {
                lib.push_str(&format!("{} : {},", reg_mod_name, reg_type_name));
            }
        }
        lib.push_str(" } impl RegisterBlock { ");
        for reg in &periph.registers {
            let reg_mod_fmt = config.ident_formats.get("register_mod").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
            let accessor_fmt = config.ident_formats.get("register_accessor").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
            let reg_mod_name = format_ident(&reg.name, &reg_mod_fmt);
            let reg_type_fmt = config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
            let reg_type_name = format_ident(&reg.name.replace("%s",""), &reg_type_fmt);
            let accessor_name = format_ident(&reg.name, &accessor_fmt);
            if let Some(dim) = reg.dim {
                if reg.dim_index.as_ref().map(|s| s.contains(',')).unwrap_or(false) {
                    let indices: Vec<&str> = reg.dim_index.as_ref().unwrap().split(',').collect();
                    for idx in indices {
                        let trimmed = idx.trim();
                        let fname = format!("{}{}", reg_mod_name, trimmed.to_lowercase());
                        let aname = format!("{}{}", accessor_name, trimmed.to_lowercase());
                        let tname = format_ident(&reg.name.replace("%s", trimmed), &reg_type_fmt);
                        lib.push_str(&format!("#[doc = \"0x{:x} - {}\"]\n#[inline (always)] pub const fn {} (& self) -> & {} {{ & self . {} }}", reg.offset, reg.description, aname, tname, fname));
                    }
                } else {
                    lib.push_str(&format!("#[doc = \"0x{:x}..0x{:x} - {}\"]\n#[inline (always)] pub const fn {} (& self , n : usize) -> & {} {{ & self . {} [n] }} #[doc = \"Iterator for array of:\"]\n#[doc = \"0x{:x}..0x{:x} - {}\"]\n#[inline (always)] pub fn {}_iter (& self) -> impl Iterator < Item = & {} > {{ self . {} . iter () }}", reg.offset, reg.offset + (dim as u64 * reg.dim_inc.unwrap_or(4)), reg.description, accessor_name, reg_type_name, reg_mod_name, reg.offset, reg.offset + (dim as u64 * reg.dim_inc.unwrap_or(4)), reg.description, accessor_name, reg_type_name, reg_mod_name));
                }
            } else {
                lib.push_str(&format!("#[doc = \"0x{:02x} - {}\"]\n#[inline (always)] pub const fn {} (& self) -> & {} {{ & self . {} }}", reg.offset, reg.description, accessor_name, reg_type_name, reg_mod_name));
            }
        }
        lib.push_str(" }\n");

        for reg in &periph.registers {
            let reg_type_fmt = config.ident_formats.get("register").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
            let reg_type_name = format_ident(&reg.name.replace("%s",""), &reg_type_fmt);
            let reg_mod_name = reg.name.to_lowercase().replace("%s","");

            let doc = format!("{} (rw) register accessor: {}\n\nYou can [`read`](crate::Reg::read) this register and get [`{}::R`]. You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`]. You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).\n\nFor information about available fields see [`mod@{}`] module", reg_type_name, reg.description, reg_mod_name, reg_mod_name, reg_mod_name);

            lib.push_str(&format!("#[doc = \"{}\"]\n", doc.replace('"', "\\\"")));
            lib.push_str(&format!("#[doc (alias = \"{}\")] pub type {} = crate :: Reg < {} :: {}Spec > ;\n", reg.name.to_uppercase(), reg_type_name, reg_mod_name, reg_type_name));
            lib.push_str(&format!("#[doc = \"{}\"] pub mod {} {{\n", reg.description.replace('"', "\\\""), reg_mod_name));
            lib.push_str(&format!("#[doc = \"Register `{}` reader\"] pub type R = crate :: R < {}Spec > ;\n", reg.name, reg_type_name));
            lib.push_str(&format!("#[doc = \"Register `{}` writer\"] pub type W = crate :: W < {}Spec > ;\n", reg.name, reg_type_name));

            for field in &reg.fields {
                let reader_fmt = config.ident_formats.get("field_reader").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "R".to_string()));
                let writer_fmt = config.ident_formats.get("field_writer").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "W".to_string()));
                let reader_name = format_ident(&field.name, &reader_fmt);
                let writer_name = format_ident(&field.name, &writer_fmt);
                lib.push_str(&format!("#[doc = \"Field `{}` reader - {}\"] pub type {} = crate :: BitReader ;\n", field.name, field.description, reader_name));
                lib.push_str(&format!("#[doc = \"Field `{}` writer - {}\"] pub type {} < 'a , REG > = crate :: BitWriter < 'a , REG > ;", field.name, field.description, writer_name));
            }

            if !reg.fields.is_empty() {
                lib.push_str(" impl R { ");
                for field in &reg.fields {
                    let reader_fmt = config.ident_formats.get("field_reader").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "R".to_string()));
                    let reader_name = format_ident(&field.name, &reader_fmt);
                    lib.push_str(&format!("#[doc = \"Bit {} - {}\"]\n#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ((self . bits & {}) != 0) }}", field.bit_offset, field.description, field.name.to_lowercase(), reader_name, reader_name, 1u64 << field.bit_offset));
                }
                lib.push_str(" } impl W { ");
                for field in &reg.fields {
                    let writer_fmt = config.ident_formats.get("field_writer").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "W".to_string()));
                    let writer_name = format_ident(&field.name, &writer_fmt);
                    lib.push_str(&format!("#[doc = \"Bit {} - {}\"]\n#[inline (always)] pub fn {} (& mut self) -> {}W < '_ , {}Spec > {{ {}W :: new (self , {}) }}", field.bit_offset, field.description, field.name.to_lowercase(), writer_name, reg_type_name, writer_name, field.bit_offset));
                }
                lib.push_str(" } ");
            }

            lib.push_str(&format!("#[doc = \"{}\\n\\nYou can [`read`](crate::Reg::read) this register and get [`{}::R`](R). You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`](W). You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).\"] pub struct {}Spec ; impl crate :: RegisterSpec for {}Spec {{ type Ux = u{} ; }}\n", reg.description.replace('"', "\\\""), reg_mod_name, reg_mod_name, reg_type_name, reg_type_name, reg.size));
            lib.push_str(&format!("#[doc = \"`read()` method returns [`{}::R`](R) reader structure\"] impl crate :: Readable for {}Spec {{ }}\n", reg_mod_name, reg_type_name));
            lib.push_str(&format!("#[doc = \"`write(|w| ..)` method takes [`{}::W`](W) writer structure\"] impl crate :: Writable for {}Spec {{ type Safety = crate :: Unsafe ; }}\n", reg_mod_name, reg_type_name));
            lib.push_str(&format!("#[doc = \"`reset()` method sets {} to value 0\"] impl crate :: Resettable for {}Spec {{ }} }}\n", reg.name, reg_type_name));
        }

        lib.push_str(" }\n");
    }

    let (dev_attr, steal_code) = match config.edition {
        Edition::E2021 => ("#[no_mangle] static mut DEVICE_PERIPHERALS : bool = false ;\n".to_string(), "DEVICE_PERIPHERALS = true ;".to_string()),
        Edition::E2024 => ("#[unsafe (no_mangle)] static mut DEVICE_PERIPHERALS : bool = false ;\n".to_string(), "unsafe { DEVICE_PERIPHERALS = true }".to_string()),
    };
    lib.push_str(&dev_attr);
    lib.push_str("#[doc = r\" All the peripherals.\"]\n#[allow (non_snake_case)] pub struct Peripherals {\n");
    for periph in &device.peripherals {
        let singleton_fmt = config.ident_formats.get("peripheral_singleton").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
        let type_fmt = config.ident_formats.get("peripheral").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
        let singleton_name = format_ident(&periph.name, &singleton_fmt);
        let type_name = format_ident(&periph.name, &type_fmt);
        let mut cfg = String::new();
        if config.feature_group { if let Some(ref g) = periph.group_name { cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", g.to_lowercase())); } }
        if config.feature_peripheral { cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", periph.name.to_lowercase())); }
        lib.push_str(&format!("{}#[doc = \"{}\"] pub {} : {} ,\n", cfg, periph.name, singleton_name, type_name));
    }
    lib.push_str(" } impl Peripherals {\n#[doc = r\" Returns all the peripherals *once*.\"]\n#[cfg (feature = \"critical-section\")]\n#[inline] pub fn take () -> Option < Self > { critical_section :: with (| _ | { if unsafe { DEVICE_PERIPHERALS } { return None } Some (unsafe { Peripherals :: steal () }) }) }\n");
    lib.push_str("#[doc = r\" Unchecked version of `Peripherals::take`.\"]\n#[doc = r\"\"\n]\n#[doc = r\" # Safety\"]\n#[doc = r\"\"\n]\n#[doc = r\" Each of the returned peripherals must be used at most once.\"]\n");
    match config.edition {
        Edition::E2021 => {
            lib.push_str(&format!("#[inline] pub unsafe fn steal () -> Self {{ {} Peripherals {{ ", steal_code));
            for periph in &device.peripherals {
                let singleton_fmt = config.ident_formats.get("peripheral_singleton").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
                let type_fmt = config.ident_formats.get("peripheral").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
                let singleton_name = format_ident(&periph.name, &singleton_fmt);
                let type_name = format_ident(&periph.name, &type_fmt);
                let mut cfg = String::new();
                if config.feature_group { if let Some(ref g) = periph.group_name { cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", g.to_lowercase())); } }
                if config.feature_peripheral { cfg.push_str(&format!("#[cfg (feature = \"{}\")] ", periph.name.to_lowercase())); }
                lib.push_str(&format!("{}{} : {} :: steal () ,", cfg, singleton_name, type_name));
            }
            lib.push_str(" } } }\n");
        },
        Edition::E2024 => {
            lib.push_str("#[inline] pub unsafe fn steal () -> Self { unsafe { DEVICE_PERIPHERALS = true } Peripherals { ");
            for periph in &device.peripherals {
                let singleton_fmt = config.ident_formats.get("peripheral_singleton").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Snake), "".to_string()));
                let type_fmt = config.ident_formats.get("peripheral").cloned().unwrap_or_else(|| IdentFormat::new("".to_string(), Some(IdentCase::Pascal), "".to_string()));
                let singleton_name = format_ident(&periph.name, &singleton_fmt);
                let type_name = format_ident(&periph.name, &type_fmt);
                lib.push_str(&format!("{} : unsafe {{ {} :: steal () }} ,", singleton_name, type_name));
            }
            lib.push_str(" } } }\n");
        }
    }

    let lib_file = if config.make_mod { "mod.rs" } else { "lib.rs" };
    let _ = fs::write(out_dir.join(lib_file), lib);
    if has_device_x {
        let _ = fs::write(out_dir.join("build.rs"), build_rs_content);
        let _ = fs::write(out_dir.join("device.x"), device_x_content);
    }
}
RS
"}

