#[derive(Debug, Clone, PartialEq)] enum IdentCase { Pascal, Constant, Snake, Unchanged }
#[derive(Debug, Clone)] struct IdentFormat { prefix: String, suffix: String, case: Option<IdentCase> }
impl IdentFormat { fn new(p: String, c: Option<IdentCase>, s: String) -> Self { Self{prefix:p,suffix:s,case:c} } }
type IdentFormats = HashMap<String, IdentFormat>;

